def semver_sort(versions):
    def parse_key(v):
        # strip build metadata
        core = v.split('+', 1)[0]
        if '-' in core:
            main, pre = core.split('-', 1)
        else:
            main, pre = core, None
        major, minor, patch = (int(x) for x in main.split('.'))
        if pre is None:
            has_pre = 1  # no prerelease sorts after
            pre_ids = []
        else:
            has_pre = 0  # has prerelease sorts before
            ids = pre.split('.')
            pre_ids = []
            for ident in ids:
                if ident.isdigit():
                    pre_ids.append((0, int(ident), ''))
                else:
                    pre_ids.append((1, 0, ident))
        return (major, minor, patch, has_pre, pre_ids)

    return sorted(versions, key=parse_key)

